enhanced_schema:
{
  "tables": [
    {
      "table_name": "proteins",
      "columns": [
        {
          "name": "accession_code",
          "type": "VARCHAR",
          "description": "Unique accession code for each protein"
        },
        {
          "name": "protein_name",
          "type": "VARCHAR",
          "description": "Name of the protein"
        },
        {
          "name": "protein_length",
          "type": "INTEGER",
          "description": "Length of the protein sequence"
        },
        {
          "name": "organism",
          "type": "VARCHAR",
          "description": "Organism from which the protein is derived"
        },
        {
          "name": "sequence",
          "type": "TEXT",
          "description": "Full sequence of the protein"
        }
      ],
      "primary_key": [
        "accession_code"
      ]
    },
    {
      "table_name": "mhc_alleles",
      "columns": [
        {
          "name": "allele_id",
          "type": "INTEGER",
          "description": "Unique identifier for each allele"
        },
        {
          "name": "antigen_presenting_protein",
          "type": "VARCHAR",
          "description": "Type of MHC molecule (e.g., MHC-I, MHC-II)"
        },
        {
          "name": "allele_name",
          "type": "VARCHAR",
          "description": "Name of the allele (e.g., HLA-A*02:01)"
        },
        {
          "name": "class",
          "type": "VARCHAR",
          "description": "MHC class (e.g., Class I or Class II)"
        },
        {
          "name": "species",
          "type": "VARCHAR",
          "description": "Species associated with the allele"
        }
      ],
      "primary_key": [
        "allele_id"
      ]
    },
    {
      "table_name": "peptides",
      "columns": [
        {
          "name": "peptide_id",
          "type": "INTEGER",
          "description": "Unique identifier for each peptide"
        },
        {
          "name": "protein_accession",
          "type": "VARCHAR",
          "description": "Accession code of the protein from which the peptide is derived"
        },
        {
          "name": "seq_num",
          "type": "INTEGER",
          "description": "Sequence number of the peptide"
        },
        {
          "name": "start_pos",
          "type": "INTEGER",
          "description": "Start position of the peptide in the protein sequence"
        },
        {
          "name": "end_pos",
          "type": "INTEGER",
          "description": "End position of the peptide in the protein sequence"
        },
        {
          "name": "length",
          "type": "INTEGER",
          "description": "Length of the peptide"
        },
        {
          "name": "peptide_sequence",
          "type": "VARCHAR",
          "description": "Sequence of the peptide"
        },
        {
          "name": "modifications",
          "type": "VARCHAR",
          "description": "Post-translational modifications of the peptide"
        },
        {
          "name": "hydrophobicity_score",
          "type": "FLOAT",
          "description": "Hydrophobicity score of the peptide"
        },
        {
          "name": "is_immunogenic",
          "type": "BOOLEAN",
          "description": "Flag indicating if the peptide is immunogenic"
        }
      ],
      "primary_key": [
        "peptide_id"
      ]
    },
    {
      "table_name": "binding_scores",
      "columns": [
        {
          "name": "score_id",
          "type": "INTEGER",
          "description": "Unique identifier for each binding score record"
        },
        {
          "name": "peptide_id",
          "type": "INTEGER",
          "description": "ID of the peptide"
        },
        {
          "name": "allele_id",
          "type": "INTEGER",
          "description": "ID of the MHC allele"
        },
        {
          "name": "score",
          "type": "FLOAT",
          "description": "Binding score indicating affinity"
        },
        {
          "name": "rank",
          "type": "FLOAT",
          "description": "Rank of the binding score"
        },
        {
          "name": "experiment_id",
          "type": "INTEGER",
          "description": "ID of the experiment from which the score was derived"
        },
        {
          "name": "date_assessed",
          "type": "DATE",
          "description": "Date when the binding score was recorded"
        }
      ],
      "primary_key": [
        "score_id"
      ]
    },
    {
      "table_name": "cores",
      "columns": [
        {
          "name": "core_id",
          "type": "INTEGER",
          "description": "Unique identifier for each core sequence record"
        },
        {
          "name": "peptide_id",
          "type": "INTEGER",
          "description": "ID of the peptide"
        },
        {
          "name": "core_sequence",
          "type": "VARCHAR",
          "description": "Core sequence of the peptide"
        },
        {
          "name": "immunogenic_core",
          "type": "VARCHAR",
          "description": "Immunogenic core sequence of the peptide"
        },
        {
          "name": "core_length",
          "type": "INTEGER",
          "description": "Length of the core sequence"
        },
        {
          "name": "is_experimental",
          "type": "BOOLEAN",
          "description": "Indicates if the core sequence is derived from experimental data"
        }
      ],
      "primary_key": [
        "core_id"
      ]
    },
    {
      "table_name": "users",
      "columns": [
        {
          "name": "user_id",
          "type": "INTEGER",
          "description": "Unique identifier for each user"
        },
        {
          "name": "user_name",
          "type": "VARCHAR",
          "description": "Full name of the user"
        },
        {
          "name": "email",
          "type": "VARCHAR",
          "description": "Email address of the user"
        },
        {
          "name": "role",
          "type": "VARCHAR",
          "description": "Role of the user (e.g., researcher, bioinformatician, admin)"
        },
        {
          "name": "last_login",
          "type": "DATETIME",
          "description": "Last login time of the user"
        },
        {
          "name": "department",
          "type": "VARCHAR",
          "description": "Department of the user"
        }
      ],
      "primary_key": [
        "user_id"
      ]
    },
    {
      "table_name": "experiments",
      "columns": [
        {
          "name": "experiment_id",
          "type": "INTEGER",
          "description": "Unique identifier for each experiment"
        },
        {
          "name": "experiment_name",
          "type": "VARCHAR",
          "description": "Name of the experiment"
        },
        {
          "name": "conducted_by",
          "type": "INTEGER",
          "description": "User ID of the person who conducted the experiment"
        },
        {
          "name": "date_conducted",
          "type": "DATE",
          "description": "Date when the experiment was conducted"
        }
      ],
      "primary_key": [
        "experiment_id"
      ]
    }
  ],
  "foreign_keys": [
    {
      "source_table": "peptides",
      "column_in_source_table": "protein_accession",
      "referenced_table": "proteins",
      "column_in_referenced_table": "accession_code"
    },
    {
      "source_table": "binding_scores",
      "column_in_source_table": "peptide_id",
      "referenced_table": "peptides",
      "column_in_referenced_table": "peptide_id"
    },
    {
      "source_table": "binding_scores",
      "column_in_source_table": "allele_id",
      "referenced_table": "mhc_alleles",
      "column_in_referenced_table": "allele_id"
    },
    {
      "source_table": "binding_scores",
      "column_in_source_table": "experiment_id",
      "referenced_table": "experiments",
      "column_in_referenced_table": "experiment_id"
    },
    {
      "source_table": "cores",
      "column_in_source_table": "peptide_id",
      "referenced_table": "peptides",
      "column_in_referenced_table": "peptide_id"
    },
    {
      "source_table": "experiments",
      "column_in_source_table": "conducted_by",
      "referenced_table": "users",
      "column_in_referenced_table": "user_id"
    }
  ]
}
